raw:
{
  "summary": [
    {
      "text": "Скорость фильтрации подчиняется уравнению, тождественному по форме уравнению теплопроводности.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Решение для скорости фильтрации выражается через функцию ошибок (erf) с заменой давления на скорость.",
      "claims": [
        "c2"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Для вывода уравнения скорости умножают уравнение пьезопроводности на k/μ и дифференцируют по x.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "После изменения порядка вычисления производных получается уравнение для величины k/μ * ∂p/∂x.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Величина k/μ * ∂p/∂x тождественна скорости фильтрации w(x, t).",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Итоговое уравнение для w имеет вид ∂w/∂t = κ * ∂²w/∂x², что совпадает с уравнением теплопроводности.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "Решением является функция w = C1 * erf(x / 2√(κt)) + C2.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Начальное условие: при t=0 скорость w равна 0 во всех точках.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Граничное условие: при x=0 скорость w равна w1.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "Подстановка начального условия приводит к соотношению C1 + C2 = 0.",
      "claims": [
        "c10"
      ]
    }
  ],
  "steps": [
    {
      "text": "Умножить уравнение пьезопроводности на k/μ.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Продифференцировать обе части по координате x.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Поменять порядок вычисления смешанных производных.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Заменить комбинацию производных давления на скорость фильтрации w.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Применить решение, аналогичное решению для давления, с заменой p на w.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Определить константы интегрирования C1 и C2 из начальных и граничных условий.",
      "claims": [
        "c10"
      ]
    }
  ],
  "examples": [],
  "numbers": [],
  "formulas": [
    {
      "unit": "u486-04",
      "latex": "\\frac{k}{\\mu} \\frac{\\partial^2 p}{\\partial x \\partial t} = \\frac{k}{\\mu} \\kappa \\frac{\\partial^3 p}{\\partial x^3}",
      "vars": [
        {
          "sym": "k",
          "meaning": "проницаемость",
          "unit": "Д"
        },
        {
          "sym": "\\mu",
          "meaning": "вязкость",
          "unit": "Па·с"
        },
        {
          "sym": "p",
          "meaning": "давление",
          "unit": "Па"
        },
        {
          "sym": "\\kappa",
          "meaning": "коэффициент пьезопроводности",
          "unit": "м²/с"
        }
      ]
    },
    {
      "unit": "u486-06",
      "latex": "\\frac{\\partial}{\\partial t} \\left( \\frac{k}{\\mu} \\frac{\\partial p}{\\partial x} \\right) = \\kappa \\frac{\\partial^2}{\\partial x^2} \\left( \\frac{k}{\\mu} \\frac{\\partial p}{\\partial x} \\right)",
      "vars": [
        {
          "sym": "t",
          "meaning": "время",
          "unit": "с"
        },
        {
          "sym": "x",
          "meaning": "координата",
          "unit": "м"
        }
      ]
    },
    {
      "unit": "u486-08",
      "latex": "\\frac{k}{\\mu} \\frac{\\partial p}{\\partial x} = w(x, t)",
      "vars": [
        {
          "sym": "w",
          "meaning": "скорость фильтрации",
          "unit": "м/с"
        }
      ]
    },
    {
      "unit": "u486-10",
      "latex": "\\frac{\\partial w(x, t)}{\\partial t} = \\kappa \\frac{\\partial^2 w(x, t)}{\\partial x^2}",
      "vars": [
        {
          "sym": "w",
          "meaning": "скорость фильтрации",
          "unit": "м/с"
        },
        {
          "sym": "\\kappa",
          "meaning": "коэффициент пьезопроводности",
          "unit": "м²/с"
        }
      ]
    },
    {
      "unit": "u486-12",
      "latex": "w = C_1 \\operatorname{erf} \\left( \\frac{x}{2\\sqrt{\\kappa t}} \\right) + C_2",
      "vars": [
        {
          "sym": "C_1, C_2",
          "meaning": "константы интегрирования",
          "unit": "м/с"
        },
        {
          "sym": "erf",
          "meaning": "функция ошибок",
          "unit": "-"
        }
      ]
    },
    {
      "unit": "u486-14",
      "latex": "w(x, 0) = 0, \\quad w(0, t) = w_1",
      "vars": [
        {
          "sym": "w_1",
          "meaning": "скорость на границе",
          "unit": "м/с"
        }
      ]
    }
  ],
  "misconception": null,
  "data_meaning": {
    "input": "Проницаемость (k), вязкость (μ), коэффициент пьезопроводности (κ), координата (x), время (t).",
    "output": "Скорость фильтрации w(x, t) в любой точке пласта в любой момент времени.",
    "breaks": [
      {
        "text": "Модель применима только для прямолинейно-параллельного потока упругой жидкости.",
        "claims": [
          "c1"
        ]
      }
    ],
    "hypotheses": [
      {
        "text": "Гипотеза: в данных мониторинга скважин скорость фильтрации может быть аппроксимирована этой функцией для оценки динамики фронта.",
        "claims": []
      }
    ]
  },
  "analogy": {
    "text": "Распространение скорости фильтрации по пласту аналогично диффузии тепла в стержне: «горячая» точка (граница) передает «тепло» (скорость) внутрь среды со временем.",
    "breaks_where": "В отличие от тепла, здесь распространяется механическое поле скоростей, а не энергия, и параметры среды (k, μ) могут быть неоднородными, что усложняет задачу."
  }}
